import math

def is_power_of_two(N):
    if N <= 0:
        return False
    return (N & (N - 1) == 0)

solutions = []

# Search limits: n up to 5, x up to 15 (to find potential small solutions)
MAX_N = 5
MAX_X = 15

for n in range(2, MAX_N + 1):
    # Constraint: x > n
    for x in range(n + 1, MAX_X + 1):
        try:
            lhs = x**n + x
        except OverflowError:
            # Stop increasing x for this n if overflow occurs (unlikely with these small limits, but good practice)
            break

        target = lhs - 2

        if is_power_of_two(target):
            # k = log2(target)
            k = int(math.log2(target))

            # Check constraints again: x > n >= 2. k must be positive since target >= 2^1=2 (if x>=3, n>=2)
            # If x=3, n=2, LHS=12, target=10 (not POT)
            # If x=3, n=3, LHS=30, target=28 (not POT)
            # If x=2, n=2, we skip this since x>n is required.

            if k >= 1: # k must be a positive integer
                solutions.append((x, n, k))

print("Solutions found (x, n, k):")
for sol in solutions:
    print(sol)

